1	// --- Price list: insurance values and base premiums ---
2	
3	/** The price list states one insurance value and one base premium per item kind. */
4	interface ListedPrice {
5	  insuranceValue: number;
6	  basePremium: number;
7	}
8	
9	const MAIN_ITEM_PRICE_LIST: Record<string, ListedPrice> = {
10	  sword: { insuranceValue: 1000, basePremium: 100 },
11	  amulet: { insuranceValue: 600, basePremium: 60 },
12	  staff: { insuranceValue: 800, basePremium: 80 },
13	  potion: { insuranceValue: 400, basePremium: 40 },
14	};
15	
16	const COMPONENT_PRICE: ListedPrice = { insuranceValue: 250, basePremium: 25 };
17	const COMPONENT_BLOCK_SIZE = 3;
18	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
19	
20	// --- Premium modifiers ---
21	const CURSE_SURCHARGE = 0.5;
22	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
23	const SURCHARGED_ENCHANTMENT_LEVEL = 5;
24	const FOLLOW_UP_CONTRACT_DISCOUNT = 0.15;
25	const LOYALTY_DISCOUNT = 0.2;
26	const LOYALTY_YEARS = 2;
27	const FIRST_INSURANCE_SURCHARGE = 0.1;
28	const PROCESSING_FEE = 5;
29	
30	// --- Claim processing ---
31	const DEDUCTIBLE_PER_DAMAGE = 100;
32	const PAYOUT_CAP_MULTIPLE = 2;
33	const HALF_REIMBURSED_ENCHANTMENT_LEVEL = 8;
34	const HALF_REIMBURSEMENT = 0.5;
35	const FULLY_REIMBURSED_MATERIAL = "dragon";
36	const FULL_REIMBURSEMENT = 1;
37	/** What a damage is reimbursed at when no special clause applies. */
38	const STANDARD_REIMBURSEMENT = 1;
39	
40	export interface Customer {
41	  yearsWithMHPCO: number;
42	}
43	
44	export interface Item {
45	  type: string;
46	  material?: string;
47	  enchantment?: number;
48	  cursed?: boolean;
49	}
50	
51	export interface QuoteStep {
52	  op: "quote";
53	  items: Item[];
54	}
55	
56	export interface Damage {
57	  itemType: string;
58	  amount: number;
59	}
60	
61	export interface Incident {
62	  cause: string;
63	  damages: Damage[];
64	}
65	
66	export interface ClaimStep {
67	  op: "claim";
68	  policy: number;
69	  incident: Incident;
70	}
71	
72	export type Step = QuoteStep | ClaimStep;
73	
74	export interface Scenario {
75	  customer: Customer;
76	  steps: Step[];
77	}
78	
79	export interface ScenarioResults {
80	  results: unknown[];
81	}
82	
83	const COMPONENT_TYPES = ["rune", "moonstone"];
84	
85	/**
86	 * An item that names no enchantment carries none: a rune has no enchantment
87	 * level at all, and the MHPCO reads that as level 0 wherever a clause draws an
88	 * enchantment line.
89	 */
90	function enchantmentLevelOf(item: Item): number {
91	  return item.enchantment ?? 0;
92	}
93	
94	function isComponent(item: Item): boolean {
95	  return COMPONENT_TYPES.includes(item.type);
96	}
97	
98	/** Everything the price list prices individually, as opposed to by alike group. */
99	function isMainItem(item: Item): boolean {
100	  return item.type in MAIN_ITEM_PRICE_LIST;
101	}
102	
103	/** The MHPCO insures an item only if its type is named in the price list. */
104	function isInsurable(item: Item): boolean {
105	  return isMainItem(item) || isComponent(item);
106	}
107	
108	/**
109	 * Admission is the MHPCO's decision about what it is willing to cover at all,
110	 * taken before the contract is opened or priced: an item the price list does
111	 * not name cannot be covered, so the whole policy is refused.
112	 */
113	function admitToPolicy(items: Item[]): void {
114	  for (const item of items) {
115	    if (!isInsurable(item)) {
116	      throw new Error(`The MHPCO price list covers no item of type "${item.type}".`);
117	    }
118	  }
119	}
120	
121	/** Components are "alike" when they share a component type. */
122	function groupAlikeComponents(components: Item[]): Map<string, number> {
123	  const groupSizes = new Map<string, number>();
124	  for (const component of components) {
125	    const alikeness = component.type;
126	    groupSizes.set(alikeness, (groupSizes.get(alikeness) ?? 0) + 1);
127	  }
128	  return groupSizes;
129	}
130	
131	/** A building block of 3 alike components is offered at a special base premium. */
132	function alikeComponentGroupBasePremium(groupSize: number): number {
133	  return groupSize === COMPONENT_BLOCK_SIZE
134	    ? COMPONENT_BLOCK_BASE_PREMIUM
135	    : groupSize * COMPONENT_PRICE.basePremium;
136	}
137	
138	function mainItemsBasePremium(mainItems: Item[]): number {
139	  return mainItems.reduce((sum, item) => sum + MAIN_ITEM_PRICE_LIST[item.type].basePremium, 0);
140	}
141	
142	function componentsBasePremium(components: Item[]): number {
143	  let premium = 0;
144	  for (const groupSize of groupAlikeComponents(components).values()) {
145	    premium += alikeComponentGroupBasePremium(groupSize);
146	  }
147	  return premium;
148	}
149	
150	function policyBasePremium(items: Item[]): number {
151	  return (
152	    mainItemsBasePremium(items.filter(isMainItem)) +
153	    componentsBasePremium(items.filter(isComponent))
154	  );
155	}
156	
157	/**
158	 * An item-specific surcharge is a rate on the affected item's own base premium,
159	 * not on the policy's. Only main items carry a per-item base premium; a
160	 * component's belongs to its alike group, so the specification fixes no
161	 * surcharge for a cursed or highly enchanted component.
162	 *
163	 * Open question -- no example in the specification covers one, and no test
164	 * pins the outcome, so the behaviour here is undefined rather than decided:
165	 * the lookup misses and the premium becomes NaN. Settle it with a test before
166	 * relying on it; a quote is never reached with such an item today only because
167	 * no example produces one.
168	 */
169	function surchargeOnOwnBasePremium(item: Item, rate: number): number {
170	  return MAIN_ITEM_PRICE_LIST[item.type].basePremium * rate;
171	}
172	
173	function curseSurcharge(item: Item): number {
174	  return item.cursed === true ? surchargeOnOwnBasePremium(item, CURSE_SURCHARGE) : 0;
175	}
176	
177	/**
178	 * The premium surcharge for a highly enchanted item, from enchantment level 5
179	 * upwards. The claim side draws its own, higher enchantment line at level 8 for
180	 * half reimbursement -- two separate clauses, not one threshold used twice.
181	 */
182	function highEnchantmentSurcharge(item: Item): number {
183	  return enchantmentLevelOf(item) >= SURCHARGED_ENCHANTMENT_LEVEL
184	    ? surchargeOnOwnBasePremium(item, HIGH_ENCHANTMENT_SURCHARGE)
185	    : 0;
186	}
187	
188	/** Item-specific surcharges apply to the base premium of the affected item. */
189	function itemSurcharges(items: Item[]): number {
190	  return items.reduce(
191	    (sum, item) => sum + curseSurcharge(item) + highEnchantmentSurcharge(item),
192	    0,
193	  );
194	}
195	
196	/** A customer is long-standing from 2 years of business with MHPCO onwards. */
197	function loyaltyDiscount(basePremium: number, customer: Customer): number {
198	  return customer.yearsWithMHPCO >= LOYALTY_YEARS ? basePremium * LOYALTY_DISCOUNT : 0;
199	}
200	
201	/**
202	 * Every item in a quote is treated as a first insurance, regardless of customer
203	 * history, so the initial assessment surcharge carries no condition.
204	 */
205	function firstInsuranceSurcharge(basePremium: number): number {
206	  return basePremium * FIRST_INSURANCE_SURCHARGE;
207	}
208	
209	/** Customers receive a discount on each contract after their first. */
210	function followUpContractDiscount(basePremium: number, contractOrdinal: number): number {
211	  return contractOrdinal > 1 ? basePremium * FOLLOW_UP_CONTRACT_DISCOUNT : 0;
212	}
213	
214	/** Policy-wide modifiers apply to the policy base premium (the sum of all item base premiums). */
215	function policyWideModifiers(
216	  basePremium: number,
217	  customer: Customer,
218	  contractOrdinal: number,
219	): number {
220	  return (
221	    firstInsuranceSurcharge(basePremium) -
222	    loyaltyDiscount(basePremium, customer) -
223	    followUpContractDiscount(basePremium, contractOrdinal)
224	  );
225	}
226	
227	/** Rounding always favours the MHPCO; for a premium that means rounding up. */
228	function premiumRoundedInMHPCOsFavour(premium: number): number {
229	  return Math.ceil(premium);
230	}
231	
232	/** Rounding always favours the MHPCO; for a payout that means rounding down. */
233	function payoutRoundedInMHPCOsFavour(payout: number): number {
234	  return Math.floor(payout);
235	}
236	
237	/**
238	 * The MHPCO prices a policy in one order: the policy base premium, then the
239	 * modifiers at their own scopes, then the processing fee at the very end.
240	 * Item-specific modifiers are charged against the base premium of the affected
241	 * item; policy-wide modifiers against the policy base premium. Only this final
242	 * amount is rounded -- intermediate amounts stay fractional.
243	 *
244	 * Pricing assumes an admitted policy: every item is named in the price list,
245	 * because admission is decided before a contract is opened or priced at all.
246	 */
247	function quotePremium(items: Item[], customer: Customer, contractOrdinal: number): number {
248	  const basePremium = policyBasePremium(items);
249	  return premiumRoundedInMHPCOsFavour(
250	    basePremium +
251	      itemSurcharges(items) +
252	      policyWideModifiers(basePremium, customer, contractOrdinal) +
253	      PROCESSING_FEE,
254	  );
255	}
256	
257	/**
258	 * How many contracts the customer has taken out with MHPCO up to and including
259	 * the quote at this step. Every step is a quote today, so a step's position in
260	 * the scenario is its contract ordinal.
261	 */
262	function contractOrdinalOfStep(stepIndex: number): number {
263	  return stepIndex + 1;
264	}
265	
266	/**
267	 * What the price list says one insured item is worth. This is the item's
268	 * unmodified value: premium modifiers price the risk of covering the item and
269	 * never change what it is worth, and the block offered on 3 alike components
270	 * is a premium offer, so each component is still insured at its own value.
271	 */
272	function insuranceValueOf(item: Item): number {
273	  return isComponent(item)
274	    ? COMPONENT_PRICE.insuranceValue
275	    : MAIN_ITEM_PRICE_LIST[item.type].insuranceValue;
276	}
277	
278	/** What the MHPCO would have to pay out if every insured item were destroyed. */
279	function insuranceSum(items: Item[]): number {
280	  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
281	}
282	
283	
284	/**
285	 * A policy created by a quote step: the MHPCO's remaining obligation under one
286	 * contract, measured two ways. `insuredItems` is the fixed coverage the contract
287	 * was written against; `remainingCap` is the money left under it, derived from
288	 * that coverage at opening and drawn down by each claim. They belong together
289	 * because the cap is a function of the coverage, not an unrelated counter.
290	 */
291	interface Policy {
292	  insuredItems: Item[];
293	  remainingCap: number;
294	}
295	
296	function openPolicy(items: Item[]): Policy {
297	  return { insuredItems: items, remainingCap: insuranceSum(items) * PAYOUT_CAP_MULTIPLE };
298	}
299	
300	/**
301	 * Damage to an item of enchantment level 8 or more is reimbursed at half the
302	 * damage amount. This is the claim side's own enchantment line, above the
303	 * level 5 that earns a premium surcharge.
304	 */
305	function isHalfReimbursed(item: Item): boolean {
306	  return enchantmentLevelOf(item) >= HALF_REIMBURSED_ENCHANTMENT_LEVEL;
307	}
308	
309	/** Damage to an item made of dragon material is fully reimbursed. */
310	function isFullyReimbursed(item: Item): boolean {
311	  return item.material === FULLY_REIMBURSED_MATERIAL;
312	}
313	
314	/**
315	 * The fraction of a damage amount the reimbursement clauses allow for this
316	 * item, before the deductible is taken. This is the one place a clause is
317	 * chosen, and the order is the specification's precedence rule rather than an
318	 * accident of writing: where both special clauses cover an item, "the 50 %
319	 * rule wins", so half reimbursement is tested first. Failing both, the damage
320	 * is reimbursed at the standard rate.
321	 *
322	 * The two clauses draw on separate knowledge and can change apart -- one reads
323	 * an enchantment level, the other a material -- so that full reimbursement
324	 * currently equals the standard rate is a coincidence of the present price
325	 * book, not one fact written twice. The clause says "full reimbursement is
326	 * owed here"; the standard rate says "no clause applies". No example can tell
327	 * them apart today, which is why the dragon clause is stated and not inferred.
328	 */
329	function reimbursementRateFor(damagedItem: Item): number {
330	  if (isHalfReimbursed(damagedItem)) return HALF_REIMBURSEMENT;
331	  if (isFullyReimbursed(damagedItem)) return FULL_REIMBURSEMENT;
332	  return STANDARD_REIMBURSEMENT;
333	}
334	
335	/** The share of a damage the MHPCO reimburses before the deductible is taken. */
336	function reimbursableDamage(damage: Damage, damagedItem: Item): number {
337	  return damage.amount * reimbursementRateFor(damagedItem);
338	}
339	
340	/**
341	 * The deductible is the claimant's own share of each damage event: the MHPCO
342	 * reimburses what the damage exceeds it by.
343	 *
344	 * Adopted reading -- the specification says only that "a deductible of 100 G
345	 * applies per damage event", and fixes no outcome for a damage smaller than
346	 * the deductible. A deductible reduces a reimbursement; it does not bill the
347	 * claimant, so a damage at or below it is reimbursed at nothing rather than
348	 * at a negative amount. Settle it against the MHPCO before relying on it.
349	 */
350	function reimbursementAfterDeductible(damage: Damage, damagedItem: Item): number {
351	  const excessOverDeductible = reimbursableDamage(damage, damagedItem) - DEDUCTIBLE_PER_DAMAGE;
352	  return Math.max(excessOverDeductible, 0);
353	}
354	
355	interface ClaimResult {
356	  payout: number;
357	  remainingCap: number;
358	}
359	
360	/**
361	 * The insured item a damage entry refers to.
362	 *
363	 * The specification does reject a claim that names an item the policy does not
364	 * cover, so this throw is the start of a real MHPCO decision rather than a
365	 * type-system formality -- but no active test pins it yet, and the rejection it
366	 * will eventually serve is broader than what happens here (it also covers more
367	 * damage entries of a type than the policy insures). Treat the current throw as
368	 * unpinned: the behaviour stands, the clause is not yet designed.
369	 */
370	function damagedItemIn(policy: Policy, damage: Damage): Item {
371	  const item = policy.insuredItems.find((insured) => insured.type === damage.itemType);
372	  if (item === undefined) {
373	    throw new Error(`The policy covers no item of type "${damage.itemType}".`);
374	  }
375	  return item;
376	}
377	
378	/** What the policy's clauses owe for an incident, before the cap is consulted. */
379	function reimbursementOwed(policy: Policy, incident: Incident): number {
380	  return incident.damages.reduce(
381	    (sum, damage) => sum + reimbursementAfterDeductible(damage, damagedItemIn(policy, damage)),
382	    0,
383	  );
384	}
385	
386	/**
387	 * What the policy is still permitted to pay. The total payout per policy is
388	 * capped, so a claim for more than the cap still carries is not refused -- the
389	 * owed amount is reduced to what remains.
390	 *
391	 * This is the cap's own decision, separate from what the clauses owe: the two
392	 * answer different questions ("what does this damage deserve?" against "how
393	 * much of the contract is left?") and change on separate occasions.
394	 */
395	function payoutPermittedByCap(owed: number, remainingCap: number): number {
396	  return Math.min(owed, remainingCap);
397	}
398	
399	/**
400	 * Settling an incident both pays the claimant and uses up part of the cap the
401	 * policy carries for the rest of its life, so the settled policy is the second
402	 * half of the outcome rather than a side effect: a claim leaves the policy in a
403	 * new state, and later claims against it see that state.
404	 */
405	function settleClaim(policy: Policy, incident: Incident): { result: ClaimResult; policy: Policy } {
406	  const payout = payoutRoundedInMHPCOsFavour(
407	    payoutPermittedByCap(reimbursementOwed(policy, incident), policy.remainingCap),
408	  );
409	  const remainingCap = policy.remainingCap - payout;
410	  return {
411	    result: { payout, remainingCap },
412	    policy: { ...policy, remainingCap },
413	  };
414	}
415	
416	export function runScenario(scenario: Scenario): ScenarioResults {
417	  /** Policies opened so far, addressed the way the input does: by the index of the quote step that opened each. */
418	  const policies = new Map<number, Policy>();
419	
420	  /**
421	   * A claim naming a step that opened no policy is outside the specification --
422	   * no example and no test describes it -- so this guard exists only to keep the
423	   * lookup total for the type system.
424	   */
425	  const policyOpenedBy = (quoteStepIndex: number): Policy => {
426	    const policy = policies.get(quoteStepIndex);
427	    if (policy === undefined) {
428	      throw new Error(`No policy was created by step ${String(quoteStepIndex)}.`);
429	    }
430	    return policy;
431	  };
432	
433	  const results = scenario.steps.map((step, stepIndex) => {
434	    if (step.op === "claim") {
435	      const { result, policy } = settleClaim(policyOpenedBy(step.policy), step.incident);
436	      policies.set(step.policy, policy);
437	      return result;
438	    }
439	    admitToPolicy(step.items);
440	    policies.set(stepIndex, openPolicy(step.items));
441	    return {
442	      premium: quotePremium(step.items, scenario.customer, contractOrdinalOfStep(stepIndex)),
443	    };
444	  });
445	  return { results };
446	}
