1	import { describe, expect, it } from "vitest";
2	import { type Incident, type Item, runScenario } from "./claim-office.js";
3	
4	// Observable contract readings adopted where the specification leaves them open:
5	// - Rejections ("exits with a non-zero status code", "writes an error description
6	//   to stderr") are modelled as the scenario runner throwing an Error; the CLI
7	//   adapter translates a thrown Error into exit code 1 plus a stderr description.
8	//   The specification establishes no error type or message, so tests require only
9	//   that an Error is thrown / that the CLI exits non-zero with non-empty stderr.
10	// - "Alike" components means the same component type (2 runes + 1 moonstone is no
11	//   block), as fixed by the specification's example.
12	
13	/** The deductible the MHPCO applies per damage event, per the specification. */
14	const DEDUCTIBLE = 100;
15	
16	/**
17	 * The premium the claim office quotes for a first contract covering these items.
18	 * Customer tenure is a spec input, so it stays explicit; it defaults to the
19	 * newcomer (0 years) that every example below describes.
20	 */
21	function premiumQuotedFor(items: Item[], yearsWithMHPCO = 0): number {
22	  const { results } = runScenario({
23	    customer: { yearsWithMHPCO },
24	    steps: [{ op: "quote", items }],
25	  });
26	  return (results[0] as { premium: number }).premium;
27	}
28	
29	/**
30	 * The claim result the office settles when this incident is reported against a
31	 * freshly quoted policy covering these items -- the quote-then-claim envelope
32	 * every claim example in the specification describes.
33	 */
34	function claimSettledOn(
35	  insuredItems: Item[],
36	  incident: Incident,
37	): { payout: number; remainingCap: number } {
38	  const { results } = runScenario({
39	    customer: { yearsWithMHPCO: 0 },
40	    steps: [
41	      { op: "quote", items: insuredItems },
42	      { op: "claim", policy: 0, incident },
43	    ],
44	  });
45	  return results[1] as { payout: number; remainingCap: number };
46	}
47	
48	/**
49	 * An incident that observes a policy's cap without drawing on it.
50	 *
51	 * The insurance sum and the cap it determines have no surface of their own in
52	 * the CLI contract, so the only way to see the opening cap is to settle a claim
53	 * and read `remainingCap` back. A damage at exactly the deductible is the probe:
54	 * the deductible takes all of it, the claim pays nothing, and the opening cap
55	 * comes back untouched. Each cap test below states its own expected payout of
56	 * 0 G alongside the cap, so the probe stays visible where it is used.
57	 */
58	function damageAtTheDeductible(itemType: string): Incident {
59	  return { cause: "fire", damages: [{ itemType, amount: DEDUCTIBLE }] };
60	}
61	
62	describe("MHPCO Claim Office", () => {
63	  // --- Quote: simplest case ---
64	  it("empty item list -> premium 5 G (processing fee only)", () => {
65	    expect(premiumQuotedFor([])).toBe(5);
66	  });
67	
68	  // --- Quote: main item base premiums (price-list catalogue, one test per entry) ---
69	  it("single sword, no modifiers, 0 years, 1st contract -> premium 115 G (100 base + 10 first insurance + 5 fee)", () => {
70	    expect(premiumQuotedFor([{ type: "sword", material: "steel", enchantment: 1, cursed: false }])).toBe(115);
71	  });
72	  it("single amulet, no modifiers, 0 years, 1st contract -> premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
73	    expect(premiumQuotedFor([{ type: "amulet", material: "silver", enchantment: 1, cursed: false }])).toBe(71);
74	  });
75	  it("single staff, no modifiers, 0 years, 1st contract -> premium 93 G (80 base + 8 first insurance + 5 fee)", () => {
76	    expect(premiumQuotedFor([{ type: "staff", material: "oak", enchantment: 1, cursed: false }])).toBe(93);
77	  });
78	  it("single potion, no modifiers, 0 years, 1st contract -> premium 49 G (40 base + 4 first insurance + 5 fee)", () => {
79	    expect(premiumQuotedFor([{ type: "potion", material: "glass", enchantment: 1, cursed: false }])).toBe(49);
80	  });
81	
82	  // --- Quote: component base premiums and the building block ---
83	  it("1 rune -> base premium 25 G; premium 33 G (25 base + 2.5 first insurance + 5 fee, rounded up)", () => {
84	    expect(premiumQuotedFor([{ type: "rune" }])).toBe(33);
85	  });
86	  it("moonstones are components too: 2 moonstones -> base premium 50 G; premium 60 G", () => {
87	    expect(premiumQuotedFor([{ type: "moonstone" }, { type: "moonstone" }])).toBe(60);
88	  });
89	  it("2 runes -> base premium 50 G (no block); premium 60 G (50 base + 5 first insurance + 5 fee)", () => {
90	    expect(premiumQuotedFor([{ type: "rune" }, { type: "rune" }])).toBe(60);
91	  });
92	  it("3 runes -> base premium 60 G (block applies); premium 71 G (60 base + 6 first insurance + 5 fee)", () => {
93	    expect(premiumQuotedFor([{ type: "rune" }, { type: "rune" }, { type: "rune" }])).toBe(71);
94	  });
95	  it("4 runes -> base premium 100 G (no block -- block requires exactly 3); premium 115 G", () => {
96	    expect(premiumQuotedFor(Array.from({ length: 4 }, () => ({ type: "rune" })))).toBe(115);
97	  });
98	  it("7 runes -> base premium 175 G (no block -- block requires exactly 3); premium 198 G", () => {
99	    expect(premiumQuotedFor(Array.from({ length: 7 }, () => ({ type: "rune" })))).toBe(198);
100	  });
101	  it("2 runes + 1 moonstone -> base premium 75 G (no block: different types); premium 88 G", () => {
102	    expect(premiumQuotedFor([{ type: "rune" }, { type: "rune" }, { type: "moonstone" }])).toBe(88);
103	  });
104	  it("3 runes + 3 moonstones -> base premium 120 G (two separate blocks); premium 137 G", () => {
105	    expect(
106	      premiumQuotedFor([
107	        { type: "rune" }, { type: "rune" }, { type: "rune" },
108	        { type: "moonstone" }, { type: "moonstone" }, { type: "moonstone" },
109	      ]),
110	    ).toBe(137);
111	  });
112	
113	  // --- Quote: item-specific modifiers ---
114	  it("cursed sword adds a 50 % surcharge on that item's base premium -> 50 G added; premium 165 G", () => {
115	    expect(premiumQuotedFor([{ type: "sword", material: "steel", enchantment: 3, cursed: true }])).toBe(165);
116	  });
117	  it("sword with enchantment 5 adds a 30 % high-enchantment surcharge -> 30 G added (threshold is inclusive); premium 145 G", () => {
